const body = $input.first().json.body;
const session = body.session || {};
const language = ['es', 'en'].includes(session.language) ? session.language : 'es';
const expertiseLevel = [1, 2, 3].includes(body.expertise_level) ? body.expertise_level : 2;
const message = (body.message || '').trim();
const SWITCH_PATTERN = /\b(cancel|cancelar|salir|exit|reiniciar|instead|en cambio|start over|empezar de nuevo|switch|cambiar proceso|abortar|forget this|olvidar esto)\b/i;
const switchIntent = Boolean(body.process_id) && SWITCH_PATTERN.test(message);

const intentionNodes = body.intention_nodes || [];
const activeNodeId = body.active_node_id || null;
// A click on a tree node in the Intention Graph arrives as a one-shot active_node_override;
// parent_override_id is the same signal surviving from a prior turn where the workflow
// needed a clarifying follow-up before actually creating the new node.
const override = body.active_node_override || body.parent_override_id || null;

const result = {
  ...body,
  github_owner: 'blasvicco',
  github_repo: 'da-sapot-processes',
  current_date: new Date().toISOString().split('T')[0],
  language,
  expertise_level: expertiseLevel,
  switch_intent: switchIntent,
  process_stack: body.process_stack || [],
  process_queue: body.process_queue || [],
  intention_nodes: intentionNodes,
  active_node_id: activeNodeId,
  paused_node_ids: body.paused_node_ids || [],
  parent_override_id: override,
};

if (override) {
  // Abandon (not pause) the currently-active node: a click on the Intention Graph is a
  // deliberate jump away from it, distinct from the conversational park-and-maybe-resume
  // flow that 'paused' represents and that the Resume button independently still gates.
  result.intention_nodes = intentionNodes.map((n) => (
    n.id === activeNodeId ? { ...n, status: 'abandoned' } : n
  ));
  result.active_node_id = null;
  result.process_id = null;
  result.process_definition = null;
  result.form_state = null;
  result.awaiting_stack_resume = false;
}

return [{ json: result }];

const base = $('Parse & Enrich').first().json;
const { pending_processes, message } = base;
if (!pending_processes || !pending_processes.length) {
  return [{ json: base }];
}
const raw = (message || '').trim();
const numMatch = raw.match(/^([1-9]\d*)$/);
const alphaMatch = raw.match(/^([a-zA-Z])$/);
let index = null;
if (numMatch) index = parseInt(numMatch[1]) - 1;
if (alphaMatch) index = alphaMatch[1].toUpperCase().charCodeAt(0) - 65;
if (index === null || index < 0 || index >= pending_processes.length) {
  const lang = base.language || 'es';
  const opts = pending_processes.map((p, i) => `${i + 1}. ${p.display_name || p.name}`).join('\n');
  const msg = lang === 'en' ? `Please choose a valid option:\n${opts}` : `Por favor elige una opci\u00f3n v\u00e1lida:\n${opts}`;
  return [{ json: { ...base, message: msg, responde: true, processes: pending_processes } }];
}
const resolved = pending_processes[index];
const ref = base.github_tag || 'main';
const orgSlug = base.organization?.slug || '';
const companyDB = base.session?.database || '';
const owner = base.github_owner;
const repo = base.github_repo;
const segs = resolved.path.split('/');
const filename = segs[segs.length - 1];
const module = resolved.module || segs[segs.length - 2] || '';
const pathPrefix = segs[0] || '';
return [{ json: {
  ...base,
  matched_entry: resolved,
  standard_path: resolved.path,
  org_standard_path: `${pathPrefix}/${orgSlug}/standard/${module}/${filename}`,
  database_path: `${pathPrefix}/${orgSlug}/${companyDB}/${module}/${filename}`,
  github_ref: ref,
  github_api_base: `https://api.github.com/repos/${owner}/${repo}/contents`,
  pending_processes: null,
  processes: null,
  selection_resolved: true,
  responde: false,
}}];

const base = $('Resolve Selection').first().json;
if (!base.awaiting_stack_resume) {
  return [{ json: base }];
}
const AFFIRMATIVE_PATTERN = /\b(s[i\u00ed]|dale|ok|okay|vale|claro|continuemos|sigamos|adelante|yes|continue|go ahead|sure)\b/i;
const raw = (base.message || '').trim();
if (!AFFIRMATIVE_PATTERN.test(raw)) {
  return [{ json: { ...base, awaiting_stack_resume: false } }];
}
const stack = base.process_stack || [];
const prev = stack[stack.length - 1];
if (!prev) {
  return [{ json: { ...base, awaiting_stack_resume: false } }];
}
const pausedNodeIds = base.paused_node_ids || [];
const resumedNodeId = pausedNodeIds.length ? pausedNodeIds[pausedNodeIds.length - 1] : null;
const intentionNodes = (base.intention_nodes || []).map((n) => (
  n.id === resumedNodeId ? { ...n, status: 'active' } : n
));
return [{ json: {
  ...base,
  process_id: prev.process_id, process_definition: prev.process_definition, form_state: prev.form_state,
  process_stack: stack.slice(0, -1), awaiting_stack_resume: false,
  paused_node_ids: pausedNodeIds.slice(0, -1),
  intention_nodes: intentionNodes,
  active_node_id: resumedNodeId,
} }];

const base = $input.first().json;
const stack = base.process_stack || [];
const newEntry = base.process_id
  ? { process_id: base.process_id, process_definition: base.process_definition, form_state: base.form_state }
  : null;
const newStack = newEntry ? [...stack, newEntry] : stack;
const pausedNodeIds = base.paused_node_ids || [];
const newPausedNodeIds = newEntry && base.active_node_id ? [...pausedNodeIds, base.active_node_id] : pausedNodeIds;
const intentionNodes = (base.intention_nodes || []).map((n) => (
  n.id === base.active_node_id ? { ...n, status: 'paused', form_state: base.form_state } : n
));
return [{ json: {
  ...base,
  process_id: null,
  process_definition: null,
  form_state: null,
  pending_processes: null,
  processes: null,
  process_stack: newStack,
  paused_node_ids: newPausedNodeIds,
  intention_nodes: intentionNodes,
  active_node_id: null,
  switch_intent: false,
  selection_resolved: false,
  error: null,
  responde: false,
}}];

const STATUS = { finding: { es: 'Identificando el proceso', en: 'Identifying the process' } };
const lang = $json.language || 'es';
return [{ json: { ...$json, status_text: STATUS.finding[lang] } }];

const data = $('Status Text: Finding').first().json;
const { language, current_date, github_owner, github_repo, github_tag, message } = data;
const ref = github_tag || 'main';
const chatInput = `Today: ${current_date}. Respond in: ${language}.

STEPS:
1. Call get_file_contents with owner=${github_owner}, repo=${github_repo}, path={organization.target}/index.json, ref=${ref}. Resolve {organization.target} from the INPUT JSON below. Always call this first.
2. Match the user message to one index entry using: keywords → when_to_use → name/slug.

INPUT:
\`\`\`json
${JSON.stringify(data, null, 2)}
\`\`\``;
return [{ json: { chatInput } }];

options.systemMessage:
Intent recognition agent. Load the process index via GitHub MCP and return the best match.

OUTPUT (standardized JSON):
Single match: {"status": "match", "message": null, "form_state": null, "processes": null, ...plus all entry fields at root}
Batch (multiple instances to create): {"status": "batch", "message": null, "form_state": null, "processes": null}
No match: {"status": "no_match", "message": "<in the response language>", "form_state": null, "processes": null}
Multiple equal: {"status": "multiple_processes", "message": "<numbered list in the response language>", "processes": [...with display_name], "form_state": null}
Error: {"status": "error", "message": "<in the response language>", "form_state": null, "processes": null}

RULES:
- Return "match" whenever the user's message clearly describes an actionable request that corresponds to one process's purpose (keywords/when_to_use) — a short, terse, or briefly-worded message is still a clear match if its meaning is unambiguous (e.g. "lístame los artículos que contengan X" is clear and actionable even though it's short). Reserve "no_match" for messages that are GENUINELY unclear: a lone stray word with no verb/object (e.g. "prover"), a likely typo, random characters, or chit-chat with no actionable SAP request at all — not for clear requests that simply happen to be brief. When in doubt about whether a real, parseable request exists, prefer matching it over rejecting it.
- Return "batch" instead of "match" when the message asks to create MULTIPLE separate process instances at once — whether the data for each instance is written inline in the message itself (e.g. "crea 2 solicitudes de compra: ...", a numbered list of records) or comes from attached files (the input JSON's bucket_file_ids is non-empty and the message asks to use their content to create records). A single request — even one with several line items belonging to that one request — is still "match", not "batch": reserve "batch" for when the message clearly asks for more than one SEPARATE instance. When in doubt between "match" and "batch", prefer "match"; only use "batch" when plurality is explicit (an explicit count, "estas solicitudes", "todas", a numbered list, multiple attached files each describing separate records, etc.). Do NOT call GitHub MCP or resolve which process(es) are involved for "batch" — that resolution happens in a later step; just recognize the bulk-creation intent and return immediately.
- For "no_match", write a warm, conversational message in the user's language saying you didn't understand and inviting them to say what they need in their own words (e.g., "No logré entender tu mensaje, ¿podrías contarme qué necesitas hacer?"). This is a single friendly response, not the start of a forced back-and-forth — don't ask a follow-up question that demands a specific structured reply.
- Never fetch process definition files. Never call SAP MCP.
Return ONLY a raw JSON object — no code fences, no markdown wrapping, no extra text.

parameters.jsCode:
const STATUS = { collecting: { es: 'Recopilando informaci\u00f3n', en: 'Collecting information' } };
const lang = $json.language || 'es';
return [{ json: { ...$json, status_text: STATUS.collecting[lang] } }];

const { language, current_date, expertise_level, process_definition, form_state, message, process_queue, last_bot_message } = $('Status Text: Collecting').first().json;
if (!process_definition) {
  return [{ json: { chatInput: `{"status":"cancelled","message":"System error: process definition is missing. Please start over.","form_state":null,"processes":null}` } }];
}
const { output: _o, ...defClean } = process_definition;
const VERBOSITY = {
  1: `Ask PENDING fields one at a time. Include the field description and an example value. Ask ALL fields (required AND optional) — do not skip any optional field; ask each one individually so the user can provide a value or explicitly decline it. When FIELD STATUS shows [CONFIRMATION REQUIRED]: present a formatted summary of ALL collected data, ask the user to approve before submitting, set status to 'in_progress', and add _confirmation_shown:true to form_state. Only set status to 'confirmed' on the turn AFTER the user explicitly says yes/confirm/proceed.`,
  2: `Ask 2-3 PENDING fields together (see FIELD STATUS below). Use field labels only, no descriptions. Ask required fields; ask optional pending fields only if contextually relevant. Auto-confirm when all required fields are collected.`,
  3: `Batch ALL PENDING required fields in one message (see FIELD STATUS below). Skip descriptions, skip examples, skip optional fields. Set status to confirmed immediately when all required fields are present.`,
}[expertise_level] || `Ask 2-3 PENDING fields together. Auto-confirm.`;
const state = form_state || {};
const SKIP_KEYS = new Set(['ready', 'items_count', 'top', 'requested_fields', 'response_format', 'match_all', '_extra_fields', '_confirmation_shown']);
const filledLines = [];
const declinedLines = [];
const pendingLines = [];
for (const section of (process_definition?.form?.sections || [])) {
  if (section.multiple) {
    const items = state[section.id];
    const requiredFields = (section.fields || []).filter(f => f.required).map(f => f.id);
    const allFieldIds = (section.fields || []).map(f => f.id);
    const hasItems = Array.isArray(items) && items.length > 0;
    const isItemComplete = (item) => {
      if (expertise_level === 1) {
        // Guided: ALL defined fields must be explicitly present (null = declined, value = filled)
        return allFieldIds.every(fid => fid in item);
      }
      if (requiredFields.length > 0) {
        return requiredFields.every(fid => item[fid] !== null && item[fid] !== undefined && String(item[fid]).trim() !== '');
      }
      return Object.values(item).some(v => v !== null && v !== undefined && String(v).trim() !== '');
    };
    const completeCount = hasItems ? items.filter(isItemComplete).length : 0;
    const allComplete = hasItems && completeCount === items.length;
    const sectionRequired = section.required !== false;
    const completionLabel = expertise_level === 1 ? 'all fields' : 'all required fields';
    if (!hasItems || !allComplete) {
      const started = hasItems ? items.length : 0;
      pendingLines.push(`  [PENDING] ${section.id} (${section.label}, ${sectionRequired ? 'REQUIRED' : 'optional'} — ${started} item(s) started, ${completeCount}/${started} have ${completionLabel} filled)`);
    } else {
      filledLines.push(`  [FILLED] ${section.id} (${section.label}) — ${items.length} item(s), ${completionLabel} complete`);
    }
  } else {
    for (const field of (section.fields || [])) {
      if (SKIP_KEYS.has(field.id)) continue;
      if (field.id in state) {
        if (state[field.id] === null) {
          declinedLines.push(`  [DECLINED] ${field.id} (${field.label})`);
        } else {
          filledLines.push(`  [FILLED] ${field.id} (${field.label}) = ${JSON.stringify(state[field.id])}`);
        }
      } else {
        pendingLines.push(`  [PENDING] ${field.id} (${field.label}${field.required ? ', REQUIRED' : ', optional'})`);
      }
    }
  }
}
let completionStatus;
if (pendingLines.length === 0) {
  if (expertise_level === 1 && !state._confirmation_shown) {
    completionStatus = `  [CONFIRMATION REQUIRED] All fields collected. Present a formatted summary of all data (every FILLED and DECLINED field, and each line item with all its fields), ask the user to confirm before submitting, return status='in_progress', and include _confirmation_shown:true in form_state. Do NOT return status='confirmed' on this turn.`;
  } else {
    completionStatus = `  (all fields complete — ready to confirm)`;
  }
} else {
  completionStatus = pendingLines.join('\n');
}
const fieldStatus = [
  `## FIELD STATUS — AUTHORITATIVE (computed by code, not by LLM; overrides all other reasoning)`,
  `FILLED — already collected, do NOT ask again:`,
  filledLines.length ? filledLines.join('\n') : `  (none)`,
  `DECLINED by user — user said no, do NOT ask again:`,
  declinedLines.length ? declinedLines.join('\n') : `  (none)`,
  `PENDING — not yet complete, must be collected before confirming:`,
  completionStatus,
].join('\n');
const lastMessageContext = last_bot_message || '(none — first message in this form)';
const chatInput = `Today: ${current_date}. Respond in: ${language}.

## INTERACTION STYLE
${VERBOSITY}

${fieldStatus}

## PROCESS DEFINITION
${JSON.stringify(defClean, null, 2)}

## CURRENT FORM STATE
${JSON.stringify(state, null, 2)}

## LAST MESSAGE YOU SENT (context only, to ground a terse or batched reply — FIELD STATUS above is still authoritative for what's filled/pending)
${lastMessageContext}

## USER MESSAGE
"${message}"

## OUTPUT
In progress: {"status": "in_progress", "message": "<question in ${language}>", "form_state": {...updated...}, "processes": null}
All required fields collected: {"status": "confirmed", "message": "<brief in ${language}>", "form_state": {...complete...}, "processes": null}
Cancelled: {"status": "cancelled", "message": "<in ${language}>", "form_state": null, "processes": null}
Lookup needed: {"status": "switch_needed", "message": null, "intent": "<user lookup request>", "form_state": ${JSON.stringify(state)}, "processes": null}`;
return [{ json: { chatInput } }];

const STATUS = { submitting: { es: 'Enviando a SAP', en: 'Submitting to SAP' } };
const lang = $json.language || 'es';
return [{ json: { ...$json, status_text: STATUS.submitting[lang] } }];

const { process_definition, form_state, organization, session } = $('Status Text: Submitting').first().json;
const integ = organization?.integration || {};
const authDriver = integ.auth_driver || 'b1s';
const connection = authDriver === 'b1s'
  ? { authDriver, baseUrl: integ.base_url, username: session?.user?.username, password: session?.user?.password, companyDB: session?.database }
  : { authDriver, baseUrl: integ.base_url, token: session?.access_token };
const method = (process_definition?.api?.method || 'GET').toUpperCase();
const serviceName = process_definition?.api?.service || '';
let operationType;
if (method === 'GET') {
  const keyDef = process_definition?.query?.key;
  const keyValue = keyDef ? form_state?.[keyDef.id] : null;
  operationType = keyValue !== null && keyValue !== undefined ? 'GET_SINGLE' : 'GET_QUERY';
} else {
  operationType = 'POST_CREATE';
}
let data = null;
if (operationType === 'POST_CREATE' && Array.isArray(process_definition?.form?.sections)) {
  const payload = {};
  for (const section of process_definition.form.sections) {
    if (section.multiple) {
      const items = form_state[section.id];
      if (Array.isArray(items) && items.length > 0) {
        payload[section.sap_field] = items.map(item => {
          const line = {};
          for (const field of (section.fields || [])) {
            const val = item[field.id];
            if (val !== null && val !== undefined && val !== '') line[field.sap_field] = val;
          }
          return line;
        });
      }
    } else {
      for (const field of (section.fields || [])) {
        const val = form_state[field.id];
        if (val !== null && val !== undefined && val !== '') payload[field.sap_field] = val;
      }
    }
  }
  const extras = form_state?._extra_fields;
  if (extras && typeof extras === 'object') {
    const allResolved = Object.values(extras).every(v => v !== null && v !== undefined);
    if (allResolved) Object.assign(payload, extras);
  }
  data = payload;
}
const pipelineData = $('Status Text: Submitting').first().json;
return [{ json: { ...pipelineData, sap_operation: operationType, sap_service: serviceName, sap_connection: connection, sap_payload: data } }];

const { language, sap_service, sap_connection, process_definition, form_state } = $json;
const keyDef = process_definition.query.key;
const keyValue = form_state[keyDef.id];
const expand = process_definition.query.expand || [];
const expandLine = expand.length ? `  "expand": ${JSON.stringify(expand)},\n` : '';
const wantsJson = form_state.response_format === 'json';
const successInstruction = wantsJson
  ? `a fenced \`\`\`json code block in the message field containing the full result (after removing null fields) as raw JSON — NOT a bullet list or prose`
  : `Markdown result in ${language}, remove null fields, use schema labels`;
const chatInput = `Call sap_entity_get with these exact parameters:

CALL:
{
  "serviceName": "${sap_service}",
  "entitySet": "",
  "keyValues": { "${keyDef.sap_field}": ${JSON.stringify(keyValue)} },
${expandLine}  "connection": ${JSON.stringify(sap_connection)}
}

Success: {"status": "success", "message": "<${successInstruction}>", "form_state": null, "processes": null}
Not found / Error: {"status": "error", "message": "<user-friendly Markdown in ${language}>", "form_state": null, "processes": null}`;
return [{ json: { chatInput } }];

const { language, sap_service, sap_connection, process_definition, form_state } = $json;
const queryDef = process_definition.query;
const schemaDef = process_definition.schema_definition;
const defaultSelect = Array.isArray(queryDef.select) && queryDef.select.length
  ? queryDef.select
  : schemaDef?.list_select?.length ? schemaDef.list_select
  : schemaDef?.get_select?.length ? schemaDef.get_select
  : null;
const resolvedFilters = (queryDef.filters || [])
  .filter(f => form_state[f.id] !== null && form_state[f.id] !== undefined)
  .map(f => {
    const val = form_state[f.id];
    if (f.type === 'date') return `${f.sap_field} ${f.operator} datetime'${val}T00:00:00'`;
    if (f.type === 'string') {
      const parts = String(val).split(/,|\bor\b/i).map(p => p.trim()).filter(p => p);
      if (f.operator === 'contains') {
        const conds = parts.map(p => `substringof('${p}', ${f.sap_field})`);
        return conds.length > 1 ? '(' + conds.join(' or ') + ')' : conds[0];
      }
      if (parts.length > 1) return '(' + parts.map(p => `${f.sap_field} eq '${p}'`).join(' or ') + ')';
      return `${f.sap_field} eq '${parts[0] || val}'`;
    }
    return `${f.sap_field} ${f.operator} ${val}`;
  });
const effectiveTop = form_state.top || queryDef.top || 20;
const effectiveOrderBy = form_state.order_by || queryDef.order_by;
const requestedFields = form_state.requested_fields || form_state.select_fields;
const fieldMap = (schemaDef?.fields || []).map(f => ({ label: f.label, sap_field: f.sap_field }));
const wantsJson = form_state.response_format === 'json';
const successInstruction = wantsJson
  ? `a fenced \`\`\`json code block in the message field containing the results as a raw JSON array (using schema field ids as keys) — NOT a Markdown table`
  : `Markdown table in ${language}`;
const chatInput = `Call sap_query_entity_set with these parameters.

SERVICE: ${sap_service}
CONNECTION: ${JSON.stringify(sap_connection)}
PRE-BUILT FILTERS (apply as-is, already valid OData v2): ${resolvedFilters.length ? resolvedFilters.join(form_state.match_all ? ' and ' : ' or ') : 'none'}
DEFAULT SELECT: ${defaultSelect ? JSON.stringify(defaultSelect) : 'omit'}
TOP: ${effectiveTop}
ORDERBY: ${effectiveOrderBy ? effectiveOrderBy.map(o => o.field + ' ' + o.direction).join(',') : 'omit'}

USER REQUESTED FIELDS: ${requestedFields ? JSON.stringify(requestedFields) : '"default"'}
If the user specified fields, use this label→sap_field map to resolve them:
${JSON.stringify(fieldMap)}
If default or none specified, use DEFAULT SELECT above.

OData v2 FILTER SYNTAX RULES (SAP B1S):
- String contains: substringof('value', FieldName) — NEVER use FieldName contains 'value'
- String equals: FieldName eq 'value'
- Number equals: FieldName eq 123
- Multiple OR: (substringof('a', F) or substringof('b', F))
- AND: expr1 and expr2
The pre-built filters above already follow this syntax. Pass them to the filter parameter verbatim.

RULES:
- Omit any parameter that is null, empty, or undefined.
- Never pass null values to any parameter.
- Use default select unless user explicitly requested specific fields.
- Render results as a Markdown table using schema labels as column headers, UNLESS the user explicitly asked for JSON/raw format (see OUTPUT below) — in that case render a fenced \`\`\`json code block instead.

Success: {"status": "success", "message": "<${successInstruction}>", "form_state": null, "processes": null}
No records: {"status": "success", "message": "<no records message in ${language}>", "form_state": null, "processes": null}
Error: {"status": "error", "message": "<user-friendly Markdown in ${language}>", "form_state": null, "processes": null}`;
return [{ json: { chatInput } }];

const { language, sap_service, sap_payload, sap_connection, process_definition } = $json;
const outputParsing = process_definition?.output_parsing;
const successMsg = process_definition?.output?.success_message || 'Operation completed successfully.';
const errorMsg = process_definition?.output?.error_message || 'Operation failed: {error_detail}';
const outputParsingSection = outputParsing
  ? `## OUTPUT PARSING SPEC\n${JSON.stringify(outputParsing, null, 2)}\n\n## HOW TO BUILD THE SUCCESS MESSAGE\n- Extract every field listed in output_parsing.fields from the SAP response body.\n- Follow output_parsing.instruction exactly to decide what to display and how to format it.\n- Use this as the base success message template: "${successMsg}"\n- When the instruction says to display lines/items as a table, ALWAYS use proper Markdown table syntax — include the header row, the separator row (|---|---|...|), and one data row per item.`
  : `## SUCCESS MESSAGE TEMPLATE\n${successMsg}\n(No output_parsing spec available — fill any {placeholder} in the template with the matching value from the SAP response body.)`;
const chatInput = `Call sap_entity_create with these exact parameters. Do not modify anything:

CALL:
{
  "serviceName": "${sap_service}",
  "entitySet": "",
  "data": ${JSON.stringify(sap_payload)},
  "connection": ${JSON.stringify(sap_connection)}
}

${outputParsingSection}

Return ONLY one of these JSON objects (no markdown, no extra text):
Success:         {"status": "success",         "message": "<formatted success message in ${language}>", "form_state": null, "processes": null}
Action required: {"status": "action_required", "message": "<friendly explanation in ${language}>",      "form_state": {"_extra_fields": {"<field>": null}}, "processes": null}
Error:           {"status": "error",           "message": "<${errorMsg} rendered with SAP error detail, in ${language}>", "form_state": null, "processes": null}`;
return [{ json: { chatInput } }];

const errorText = ($json.error?.message || String($json.error || '')).trim();
const type = /rate.?limit|tokens.?per.?min|TPM|too.?large/i.test(errorText) ? 'RATE_LIMIT'
  : /parse|json|syntax/i.test(errorText) ? 'PARSE_ERROR'
  : /not.?found|404/i.test(errorText) ? 'NOT_FOUND'
  : /unauthorized|403|401/i.test(errorText) ? 'AUTH_ERROR'
