const state = $json;
const ctx = state.batch_context;
const isError = Boolean(state.error);
const doneSoFar = [...(ctx.completed_results || []), {
  item_index: ctx.item_index,
  status: isError ? 'failed' : 'completed',
  message: state.message,
  source_files: ctx.current_item?.source_files || [],
}];
const remaining = ctx.remaining_items || [];
const lang = state.language || 'es';

if (remaining.length > 0) {
  const [next, ...stillRemaining] = remaining;
  const body = {
    batch_continue: {
      batch_id: ctx.batch_id,
      item_index: ctx.item_index + 1,
      total_items: ctx.total_items,
      current_item: next,
      remaining_items: stillRemaining,
      completed_results: doneSoFar,
      intention_nodes: state.intention_nodes,
    },
    session: state.session,
    group_name: state.group_name,
    session_id: state.session_id,
    message: '__batch_auto_continue__',
    expertise_level: state.expertise_level,
    organization: state.organization,
  };
  const statusText = lang === 'en'
    ? `Processing ${ctx.item_index + 2} of ${ctx.total_items}...`
    : `Procesando ${ctx.item_index + 2} de ${ctx.total_items}...`;
  return [{ json: { self_call_body: body, status_text: statusText, group_name: state.group_name, session_id: state.session_id } }];
}

const successCount = doneSoFar.filter((r) => r.status === 'completed').length;
const failCount = doneSoFar.filter((r) => r.status === 'failed').length;
const summary = lang === 'en'
  ? `**Batch execution completed**\n\u2713 ${successCount} created successfully\n\u2717 ${failCount} failed`
    + (failCount ? '\n\nCheck the Intention Graph to review and fix the failed ones.' : '')
  : `**Ejecuci\u00f3n por lotes completada**\n\u2713 ${successCount} creadas exitosamente\n\u2717 ${failCount} fallaron`
    + (failCount ? '\n\nRevisa el Grafo de Intenciones para corregir las fallidas.' : '');
return [{ json: { ...state, message: summary, batch_context: null, reset_process: true, responde: true } }];

